- Compare cache behavior of introsort vs pure mergesort on large datasets.

## Why This Is Asked

This question tests your ability to apply k-way merge algorithms to partially sorted data, a common scenario in data processing pipelines and external sorting. It emphasizes understanding how the number of runs (r) impacts both time complexity and memory usage, connecting theoretical concepts with practical implementation.

## Key Concepts

- **k-way merge**: Efficient merging of multiple sorted sequences
- **Run detection**: Identifying sorted segments in a single linear pass
- **Min-heap**: Priority queue for selecting minimum elements efficiently
- **Complexity analysis**: O(n log r) time, O(r) auxiliary space
- **Edge cases**: Empty input, duplicate elements, and single-run scenarios

## Code Example

```javascript
class MinHeap {
  constructor() { 
    this.heap = []; 
  }

  size() { 
    return this.heap.length; 
  }

  push(item) {
    this.heap.push(item);
    this._heapifyUp(this.heap.length - 1);
  }

  pop() {
    if (this.heap.length === 0) return null;
    const min = this.heap[0];
    const last = this.heap.pop();
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this._heapifyDown(0);
    }
    return min;
  }

  _heapifyUp(index) { /* implementation */ }
  _heapifyDown(index) { /* implementation */ }
}

function kWayMerge(arr) {
  // Edge case: empty input
  if (arr.length === 0) return [];

  // Detect runs
  const runs = [];
  let start = 0;

  for (let i = 1; i <= arr.length; i++) {
    if (i === arr.length || arr[i-1] > arr[i]) {
      runs.push({start, end: i-1, index: start});
      start = i;
    }
  }

  // Edge case: r=1 (already sorted)
  if (runs.length === 1) return arr.slice();

  // Initialize heap with first elements
  const heap = new MinHeap();
  const result = [];

  runs.forEach((run, i) => {
    heap.push({value: arr[run.index], runId: i});
  });

  // Merge process
  while (heap.size() > 0) {
    const {value, runId} = heap.pop();
    result.push(value);

    const run = runs[runId];
    if (run.index < run.end) {
      run.index++;
      heap.push({value: arr[run.index], runId});
    }
  }

  return result;
}
```

## Why This Question Is Asked

This problem tests your ability to combine multiple data structures to solve a real-world analytics challenge: maintaining sliding window aggregations with fast top-K retrieval under tight latency constraints.

## Key Concepts

1. **Circular bucket array** enables O(1) bucketing and automatic expiration of old events
2. **Hashmap aggregation** provides O(1) lookup and update for per-user totals across categories
3. **Max-heap with lazy deletion** avoids the overhead of rebuilding the heap on every expiration; stale entries are filtered on-demand during `topK`
4. **Lazy expiration** ensures we never scan individual events during query time—only expired buckets trigger cleanup

## Code Example

```javascript
class WindowedTopK {
  constructor(W) {
    this.W = W;
    this.buckets = new Array(W).fill(null).map(() => ({ head: null, tail: null, ts: null }));
    this.totals = new Map();
    this.heap = [];
    this.head = 0;
  }

  insertEvent(ts, userId, category, value) {
    const idx = ts % this.W;
    const bucket = this.buckets[idx];
    const event = { userId, category, value, ts, next: null };
    if (!bucket.head) bucket.head = bucket.tail = event;
    else bucket.tail = bucket.tail.next = event;
    bucket.ts = ts;

    this.totals.set(userId, (this.totals.get(userId) || 0) + value);
    this.heap.push({ total: this.totals.get(userId), userId, ts });
  }

  advanceTime(now) {
    const cutoff = now - this.W;
    while (this.buckets[this.head].ts !== null && this.buckets[this.head].ts < cutoff) {
      let event = this.buckets[this.head].head;
      while (event) {
        this.totals.set(event.userId, (this.totals.get(event.userId) || 0) - event.value);
        event = event.next;
      }
      this.buckets[this.head] = { head: null, tail: null, ts: null };
      this.head = (this.head + 1) % this.W;
    }
  }

  topK(now, K) {
    this.advanceTime(now);
    const result = [];
    let i = 0;
    while (result.length < K && i < this.heap.length) {
      const entry = this.heap[i++];
      if (this.totals.get(entry.userId) === entry.total) {
        result.push(entry.userId);
      }
    }
    return result;
  }
}
```

## Follow-up Questions

- **Per-category top-K**: Maintain separate totals per `(userId, category)` and separate heaps for each category
- **Bounded memory**: Add a periodic rebuild phase or use LRU eviction for rarely-active user_ids
- **Distributed extension**: Partition by user_id hash across nodes, aggregate partial results

## Why This Is Asked
Explores a practical, augmented Trie approach blending prefix queries with order-statistics, a gap in typical BST/trie questions.

## Key Concepts
- Trie augmentation with endCount and subCount
- Duplicates handled via endCount
- Lexicographic kthWord via endCount before children

## Code Example
```javascript
class Node {
  constructor() {
    this.next = new Map();
    this.end = 0;
    this.sub = 0;
  }
}
class Trie {
  constructor(){ this.root = new Node(); }
  insert(w){ let cur=this.root; cur.sub++; for(const ch of w){ if(!cur.next.has(ch)) cur.next.set(ch,new Node()); cur=cur.next.get(ch); cur.sub++; } cur.end++; }
  delete(w){ let cur=this.root; cur.sub--; for(const ch of w){ cur=cur.next.get(ch); cur.sub--; } cur.end--; }
  countPrefix(p){ let cur=this.root; for(const ch of p){ if(!cur.next.has(ch)) return 0; cur=cur.next.get(ch); } return cur.sub; }
  kthWord(k){ let res=''; let node=this.root; while(true){ if(k <= node.end) return res; k -= node.end; // skip words ending here
      // iterate in lexical order
      const keys = Array.from(node.next.keys()).sort();
      for(const ch of keys){ const child=node.next.get(ch); if(child.sub >= k){ res += ch; node = child; break; } else k -= child.sub; }
    }
  }
}
```

